def restore_bond_balances(apps, schema_editor):
    VendorProfile = apps.get_model("catalog", "VendorProfile")
    LedgerEntry = apps.get_model("ledger", "LedgerEntry")
    database = schema_editor.connection.alias

    for profile in (
        VendorProfile.objects.using(database).select_related("bond_account").iterator()
    ):
        amount = (
            LedgerEntry.objects.using(database)
            .filter(account_id=profile.bond_account_id)
            .aggregate(total=models.Sum("amount"))["total"]
            or 0
        )
        profile.bond_amount = amount
        profile.save(using=database, update_fields=("bond_amount",))


def move_bond_balances_to_ledger(apps, schema_editor):
    VendorProfile = apps.get_model("catalog", "VendorProfile")
    Account = apps.get_model("ledger", "Account")
    LedgerEntry = apps.get_model("ledger", "LedgerEntry")
    database = schema_editor.connection.alias

    treasury = (
        Account.objects.using(database).filter(kind="treasury").order_by("pk").first()
    )

    for profile in VendorProfile.objects.using(database).all().iterator():
        bond_account = Account.objects.using(database).create(kind="vendor_bond")
        profile.bond_account_id = bond_account.pk
        profile.save(using=database, update_fields=("bond_account",))
        if profile.bond_amount:
            if treasury is None:
                treasury = Account.objects.using(database).create(kind="treasury")
            reference = f"vendor-bond-migration-{profile.pk}"
            LedgerEntry.objects.using(database).create(
                account_id=treasury.pk,
                amount=-profile.bond_amount,
                ref=reference,
            )
            LedgerEntry.objects.using(database).create(
                account_id=bond_account.pk,
                amount=profile.bond_amount,
                ref=reference,
            )


